-- Microsoft Clarity CSV import. Source timestamps have no supplied timezone.
BEGIN;
CREATE SCHEMA IF NOT EXISTS clarity;

CREATE TABLE clarity.dashboard_2026_10_14 (
  source_row integer PRIMARY KEY CHECK (source_row > 0),
  row_kind text NOT NULL CHECK (row_kind IN ('metadata','section','header','data')),
  metric text,
  label text,
  value_text text,
  value_numeric numeric,
  value_unit text,
  sessions bigint,
  percentage numeric,
  details jsonb NOT NULL,
  source_headers jsonb NOT NULL,
  raw_fields jsonb NOT NULL CHECK (jsonb_typeof(raw_fields) = 'array'),
  project_name text NOT NULL DEFAULT 'ZiaFlow',
  source_file text NOT NULL DEFAULT 'Clarity_ZiaFlow_Dashboard_10-14-2026 10 35 AM.csv',
  source_sha256 text NOT NULL DEFAULT 'ca886dce8ead65849171fc7e95df6442cba8cf19c1a87c689bcc23d48aa6b2e8',
  period_start timestamp without time zone NOT NULL DEFAULT '2026-07-17 00:00:00',
  period_end timestamp without time zone NOT NULL DEFAULT '2026-10-14 23:59:00',
  exported_at timestamp without time zone NOT NULL DEFAULT '2026-10-14 10:35:00',
  imported_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE clarity.dashboard_2026_10_14 IS 'Complete nonblank source rows from Clarity_ZiaFlow_Dashboard_10-14-2026 10 35 AM.csv. Filter row_kind = data for metric records. Overlapping reporting windows are snapshots, not daily metrics. Source timestamp timezone is unspecified.';
ALTER TABLE clarity.dashboard_2026_10_14 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON clarity.dashboard_2026_10_14 FROM PUBLIC, anon, authenticated;
GRANT ALL ON clarity.dashboard_2026_10_14 TO service_role;
DO $verify$ BEGIN
  IF (SELECT count(*) FROM clarity.dashboard_2026_10_14) <> 100 THEN RAISE EXCEPTION 'Source row count mismatch for dashboard_2026_10_14'; END IF;
  IF (SELECT count(*) FROM clarity.dashboard_2026_10_14 WHERE row_kind = 'data') <> 79 THEN RAISE EXCEPTION 'Data row count mismatch for dashboard_2026_10_14'; END IF;
  IF (SELECT value_numeric FROM clarity.dashboard_2026_10_14 WHERE metric = 'Sessions' AND label = 'Total sessions') <> 426 THEN RAISE EXCEPTION 'Session total mismatch for dashboard_2026_10_14'; END IF;
END $verify$;

CREATE TABLE clarity.dashboard_2026_09_29 (
  source_row integer PRIMARY KEY CHECK (source_row > 0),
  row_kind text NOT NULL CHECK (row_kind IN ('metadata','section','header','data')),
  metric text,
  label text,
  value_text text,
  value_numeric numeric,
  value_unit text,
  sessions bigint,
  percentage numeric,
  details jsonb NOT NULL,
  source_headers jsonb NOT NULL,
  raw_fields jsonb NOT NULL CHECK (jsonb_typeof(raw_fields) = 'array'),
  project_name text NOT NULL DEFAULT 'ZiaFlow',
  source_file text NOT NULL DEFAULT 'Clarity_ZiaFlow_Dashboard_09-29-2026 05 24 PM.csv',
  source_sha256 text NOT NULL DEFAULT '9b26a47838aa881ebe3a1a6aa684b85f71e292a5b7e4abaf2c0e3140d65aaeca',
  period_start timestamp without time zone NOT NULL DEFAULT '2026-07-02 00:00:00',
  period_end timestamp without time zone NOT NULL DEFAULT '2026-09-29 23:59:00',
  exported_at timestamp without time zone NOT NULL DEFAULT '2026-09-29 17:24:00',
  imported_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE clarity.dashboard_2026_09_29 IS 'Complete nonblank source rows from Clarity_ZiaFlow_Dashboard_09-29-2026 05 24 PM.csv. Filter row_kind = data for metric records. Overlapping reporting windows are snapshots, not daily metrics. Source timestamp timezone is unspecified.';
ALTER TABLE clarity.dashboard_2026_09_29 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON clarity.dashboard_2026_09_29 FROM PUBLIC, anon, authenticated;
GRANT ALL ON clarity.dashboard_2026_09_29 TO service_role;
DO $verify$ BEGIN
  IF (SELECT count(*) FROM clarity.dashboard_2026_09_29) <> 100 THEN RAISE EXCEPTION 'Source row count mismatch for dashboard_2026_09_29'; END IF;
  IF (SELECT count(*) FROM clarity.dashboard_2026_09_29 WHERE row_kind = 'data') <> 84 THEN RAISE EXCEPTION 'Data row count mismatch for dashboard_2026_09_29'; END IF;
  IF (SELECT value_numeric FROM clarity.dashboard_2026_09_29 WHERE metric = 'Sessions' AND label = 'Total sessions') <> 414 THEN RAISE EXCEPTION 'Session total mismatch for dashboard_2026_09_29'; END IF;
END $verify$;

COMMIT;
SELECT 'clarity.dashboard_2026_10_14' AS table_name, count(*) AS source_rows, count(*) FILTER (WHERE row_kind = 'data') AS data_rows FROM clarity.dashboard_2026_10_14
UNION ALL
SELECT 'clarity.dashboard_2026_09_29' AS table_name, count(*) AS source_rows, count(*) FILTER (WHERE row_kind = 'data') AS data_rows FROM clarity.dashboard_2026_09_29;
